CREATE OR REPLACE FUNCTION public.bundle_available_quantity(p_bundle_id uuid, p_selections jsonb DEFAULT '[]'::jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_item record;
  v_product record;
  v_variant record;
  v_variant_id uuid;
  v_inventory int;
  v_max int := null;
  v_candidate int;
begin
  for v_item in
    select * from public.product_bundle_items
    where bundle_id = p_bundle_id
    order by sort_order, created_at
  loop
    select * into v_product from public.products p
    where p.id = v_item.product_id and p.published = true;

    if v_product.id is null then
      return 0;
    end if;

    v_variant_id := public.resolve_bundle_item_variant(v_item.id, p_selections);

    if v_variant_id is not null then
      select * into v_variant from public.product_variants pv
      where pv.id = v_variant_id and pv.product_id = v_product.id and pv.is_active = true;
      if v_variant.id is null then
        return 0;
      end if;
      v_inventory := v_variant.inventory_count;
    elsif exists (select 1 from public.product_variants pv where pv.product_id = v_product.id and pv.is_active = true) then
      return 0;
    else
      v_inventory := v_product.inventory_count;
    end if;

    v_candidate := floor(v_inventory::numeric / greatest(1, v_item.quantity));
    v_max := least(coalesce(v_max, v_candidate), v_candidate);
  end loop;

  return coalesce(v_max, 0);
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_bundle_item_variant(p_bundle_item_id uuid, p_selections jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_item record;
  v_sel_variant uuid;
begin
  select * into v_item from public.product_bundle_items where id = p_bundle_item_id;
  if v_item.id is null then
    return null;
  end if;

  if v_item.variant_id is not null then
    return v_item.variant_id;
  end if;

  select nullif(elem->>'variant_id', '')::uuid into v_sel_variant
  from jsonb_array_elements(coalesce(p_selections, '[]'::jsonb)) elem
  where nullif(elem->>'bundle_item_id', '')::uuid = p_bundle_item_id
  limit 1;

  return v_sel_variant;
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_coupon_discount(p_code text, p_subtotal numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_coupon record;
  v_discount numeric(10,2);
begin
  if nullif(trim(p_code), '') is null then
    return jsonb_build_object('ok', true, 'discount', 0, 'code', null);
  end if;

  select * into v_coupon from public.coupons
  where upper(code) = upper(trim(p_code)) and is_active = true;

  if v_coupon.id is null then
    return jsonb_build_object('ok', false, 'error', 'Invalid coupon code');
  end if;
  if v_coupon.starts_at is not null and v_coupon.starts_at > now() then
    return jsonb_build_object('ok', false, 'error', 'Coupon is not active yet');
  end if;
  if v_coupon.expires_at is not null and v_coupon.expires_at < now() then
    return jsonb_build_object('ok', false, 'error', 'Coupon has expired');
  end if;
  if v_coupon.max_uses is not null and v_coupon.used_count >= v_coupon.max_uses then
    return jsonb_build_object('ok', false, 'error', 'Coupon usage limit reached');
  end if;
  if p_subtotal < v_coupon.min_subtotal then
    return jsonb_build_object('ok', false, 'error', 'Minimum order not met for this coupon');
  end if;

  if v_coupon.discount_type = 'percent' then
    v_discount := round(p_subtotal * least(100, v_coupon.discount_value) / 100, 2);
  else
    v_discount := least(p_subtotal, v_coupon.discount_value);
  end if;

  return jsonb_build_object(
    'ok', true,
    'discount', v_discount,
    'code', v_coupon.code,
    'coupon_id', v_coupon.id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_product_delivery_text(p_product_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_product public.products%rowtype;
  v_default text;
begin
  select * into v_product from public.products where id = p_product_id;
  if not found then return null; end if;

  if coalesce(v_product.use_default_delivery, true) then
    select value into v_default from public.site_settings where key = 'default_delivery_info' limit 1;
    if v_default is not null and btrim(v_default) <> '' then
      return v_default;
    end if;
    select body_html into v_default
    from public.marketing_pages
    where slug = 'shipping' and published = true
    limit 1;
    return v_default;
  end if;

  return nullif(btrim(coalesce(v_product.delivery_info, '')), '');
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_shipping_rate(p_country text, p_subtotal numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_zone record;
  v_country text := upper(coalesce(nullif(trim(p_country), ''), 'DEFAULT'));
  v_default_rate numeric;
  v_free_threshold numeric;
begin
  select coalesce((select value::numeric from public.site_settings where key = 'default_flat_shipping_rate' limit 1), 9.99)
  into v_default_rate;
  select nullif((select value from public.site_settings where key = 'free_shipping_threshold' limit 1), '')::numeric
  into v_free_threshold;

  for v_zone in
    select * from public.shipping_zones where is_active = true order by sort_order, name
  loop
    if jsonb_array_length(v_zone.countries) = 0 then
      if coalesce(v_zone.free_shipping_threshold, v_free_threshold) is not null
         and p_subtotal >= coalesce(v_zone.free_shipping_threshold, v_free_threshold) then
        return 0;
      end if;
      return v_zone.flat_rate;
    end if;
    if exists (
      select 1 from jsonb_array_elements_text(v_zone.countries) c
      where upper(c.value) = v_country
    ) then
      if v_zone.free_shipping_threshold is not null and p_subtotal >= v_zone.free_shipping_threshold then
        return 0;
      end if;
      return v_zone.flat_rate;
    end if;
  end loop;

  if v_free_threshold is not null and p_subtotal >= v_free_threshold then
    return 0;
  end if;
  return v_default_rate;
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_admin_fulfill_order_inventory(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'error', 'Forbidden');
  end if;
  return public.rpc_fulfill_order_inventory(p_order_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_can_review_product(p_product_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    return jsonb_build_object('ok', true, 'can_review', false, 'reason', 'sign_in');
  end if;

  if exists (select 1 from public.product_reviews where product_id = p_product_id and user_id = v_uid) then
    return jsonb_build_object('ok', true, 'can_review', false, 'reason', 'already_reviewed');
  end if;

  if not public.user_has_purchased_product(p_product_id, v_uid) then
    return jsonb_build_object('ok', true, 'can_review', false, 'reason', 'not_purchased');
  end if;

  return jsonb_build_object('ok', true, 'can_review', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_check_rate_limit(p_action text, p_identifier text, p_max_requests integer DEFAULT 10, p_window_seconds integer DEFAULT 3600)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count int;
begin
  delete from public.rate_limit_events
  where created_at < now() - make_interval(secs => p_window_seconds);

  select count(*)::int into v_count
  from public.rate_limit_events
  where action = p_action
    and identifier = p_identifier
    and created_at > now() - make_interval(secs => p_window_seconds);

  if v_count >= p_max_requests then
    return jsonb_build_object('ok', false, 'error', 'Too many requests. Please try again later.');
  end if;

  insert into public.rate_limit_events (action, identifier)
  values (p_action, left(p_identifier, 256));

  return jsonb_build_object('ok', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_fulfill_order_inventory(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_line record;
  v_order record;
  v_component jsonb;
  v_variant_id uuid;
begin
  select * into v_order from public.orders where id = p_order_id;
  if v_order.id is null then
    return jsonb_build_object('ok', false, 'error', 'Order not found');
  end if;
  if v_order.status = 'paid' and coalesce(v_order.metadata->>'inventory_fulfilled', 'false') = 'true' then
    return jsonb_build_object('ok', true, 'skipped', true);
  end if;

  for v_line in select * from public.order_items where order_id = p_order_id
  loop
    if v_line.bundle_id is not null then
      for v_component in select * from jsonb_array_elements(coalesce(v_line.metadata->'components', '[]'::jsonb))
      loop
        v_variant_id := nullif(v_component->>'variant_id', '')::uuid;
        if v_variant_id is not null then
          update public.product_variants
          set inventory_count = greatest(0, inventory_count - greatest(1, (v_component->>'quantity')::int)),
              updated_at = now()
          where id = v_variant_id;
        elsif nullif(v_component->>'product_id', '') is not null then
          update public.products
          set inventory_count = greatest(0, inventory_count - greatest(1, (v_component->>'quantity')::int)),
              updated_at = now()
          where id = (v_component->>'product_id')::uuid;
        end if;
      end loop;
    elsif v_line.variant_id is not null then
      update public.product_variants
      set inventory_count = greatest(0, inventory_count - v_line.quantity),
          updated_at = now()
      where id = v_line.variant_id;
    elsif v_line.product_id is not null then
      update public.products
      set inventory_count = greatest(0, inventory_count - v_line.quantity),
          updated_at = now()
      where id = v_line.product_id;
    end if;
  end loop;

  update public.orders
  set metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('inventory_fulfilled', true),
      updated_at = now()
  where id = p_order_id;

  return jsonb_build_object('ok', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_get_admin_dashboard()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_daily jsonb;
  v_weekly jsonb;
  v_monthly jsonb;
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'error', 'Forbidden');
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'label', initcap(trim(to_char(d.day_date, 'Day'))),
      'short_label', to_char(d.day_date, 'Dy'),
      'date', d.day_date,
      'count', coalesce(o.cnt, 0),
      'is_current', d.day_date = current_date
    )
    order by d.day_date
  ), '[]'::jsonb)
  into v_daily
  from (
    select gs::date as day_date
    from generate_series(
      date_trunc('week', current_date)::date,
      date_trunc('week', current_date)::date + interval '6 days',
      interval '1 day'
    ) gs
  ) d
  left join lateral (
    select count(*)::int as cnt
    from public.orders ord
    where ord.created_at::date = d.day_date
  ) o on true;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'label', initcap(trim(to_char(d.day_date, 'Day'))),
      'short_label', to_char(d.day_date, 'Dy'),
      'date', d.day_date,
      'count', coalesce(o.cnt, 0),
      'is_current', d.day_date = current_date
    )
    order by d.day_date
  ), '[]'::jsonb)
  into v_weekly
  from (
    select gs::date as day_date
    from generate_series(
      current_date - interval '6 days',
      current_date,
      interval '1 day'
    ) gs
  ) d
  left join lateral (
    select count(*)::int as cnt
    from public.orders ord
    where ord.created_at::date = d.day_date
  ) o on true;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'label', to_char(m.month_start, 'Mon'),
      'year', extract(year from m.month_start)::int,
      'month', extract(month from m.month_start)::int,
      'count', coalesce(o.cnt, 0),
      'is_current', m.month_start = date_trunc('month', current_date)::date
    )
    order by m.month_start
  ), '[]'::jsonb)
  into v_monthly
  from (
    select gs::date as month_start
    from generate_series(
      (date_trunc('month', current_date) - interval '11 months')::date,
      date_trunc('month', current_date)::date,
      interval '1 month'
    ) gs
  ) m
  left join lateral (
    select count(*)::int as cnt
    from public.orders ord
    where date_trunc('month', ord.created_at)::date = m.month_start
  ) o on true;

  return jsonb_build_object(
    'ok', true,
    'counts', jsonb_build_object(
      'products', (select count(*) from public.products),
      'collections', (select count(*) from public.collections),
      'unread_quotes', (
        select count(*)
        from public.orders ord
        where ord.status = 'quote_requested'
          and ord.admin_viewed_at is null
      ),
      'unread_submissions', (
        select count(*)
        from public.form_submissions fs
        where fs.admin_viewed_at is null
      ),
      'media', (select count(*) from public.cms_media),
      'total_sales', coalesce((
        select sum(ord.total)
        from public.orders ord
        where ord.status not in ('failed', 'cancelled', 'refunded')
      ), 0)
    ),
    'recent_newsletter', coalesce((
      select jsonb_agg(to_jsonb(n) order by n.created_at desc)
      from (
        select ns.*
        from public.newsletter_subscribers ns
        order by ns.created_at desc
        limit 5
      ) n
    ), '[]'::jsonb),
    'order_chart', jsonb_build_object(
      'daily', v_daily,
      'weekly', v_weekly,
      'monthly', v_monthly
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_get_admin_edit_context()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'error', 'Forbidden');
  end if;

  return jsonb_build_object(
    'ok', true,
    'categories', coalesce((
      select jsonb_agg(to_jsonb(c) order by c.sort_order, c.name)
      from public.categories c
    ), '[]'::jsonb),
    'collections', coalesce((
      select jsonb_agg(to_jsonb(c) order by c.sort_order, c.title)
      from public.collections c
    ), '[]'::jsonb)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_get_admin_session()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_role text;
  v_active boolean;
begin
  select au.role, au.is_active
  into v_role, v_active
  from public.admin_users au
  where au.auth_user_id = (select auth.uid())
  limit 1;

  if v_role is null or not coalesce(v_active, false) then
    return jsonb_build_object('ok', true, 'is_admin', false, 'can_edit', false, 'role', null);
  end if;

  return jsonb_build_object(
    'ok', true,
    'is_admin', v_role in ('owner', 'admin', 'editor'),
    'can_edit', v_role in ('owner', 'admin', 'editor'),
    'role', v_role
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_get_cart_totals(p_items jsonb, p_currency text DEFAULT NULL::text, p_shipping_country text DEFAULT NULL::text, p_coupon_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_currency text;
  v_subtotal numeric(10,2) := 0;
  v_item jsonb;
  v_product record;
  v_variant record;
  v_bundle record;
  v_bundle_item record;
  v_qty int;
  v_line numeric(10,2);
  v_unit_price numeric(10,2);
  v_inventory int;
  v_reserved int;
  v_name text;
  v_image text;
  v_items_out jsonb := '[]'::jsonb;
  v_variant_id uuid;
  v_variant_name text;
  v_bundle_id uuid;
  v_selections jsonb;
  v_components jsonb;
  v_sel_variant uuid;
  v_available int;
  v_component jsonb;
  v_shipping numeric(10,2);
  v_tax_rate numeric(10,2);
  v_tax numeric(10,2);
  v_discount numeric(10,2) := 0;
  v_coupon jsonb;
  v_total numeric(10,2);
begin
  select coalesce(p_currency, (select value from public.site_settings where key = 'currency_code' limit 1), 'USD')
  into v_currency;

  for v_item in select * from jsonb_array_elements(coalesce(p_items, '[]'::jsonb))
  loop
    v_qty := greatest(1, (v_item->>'quantity')::int);
    v_bundle_id := nullif(v_item->>'bundle_id', '')::uuid;

    if v_bundle_id is not null then
      v_selections := coalesce(v_item->'selections', '[]'::jsonb);
      select * into v_bundle from public.product_bundles b where b.id = v_bundle_id and b.published = true;
      if v_bundle.id is null then
        return jsonb_build_object('ok', false, 'error', 'Bundle unavailable');
      end if;

      v_available := public.bundle_available_quantity(v_bundle_id, v_selections);
      if v_available < v_qty then
        return jsonb_build_object('ok', false, 'error', v_bundle.name || ' has only ' || v_available || ' available in stock');
      end if;

      v_components := '[]'::jsonb;
      for v_bundle_item in select * from public.product_bundle_items where bundle_id = v_bundle_id order by sort_order
      loop
        select * into v_product from public.products p where p.id = v_bundle_item.product_id and p.published = true;
        if v_product.id is null then
          return jsonb_build_object('ok', false, 'error', 'A bundle item is unavailable');
        end if;

        v_sel_variant := public.resolve_bundle_item_variant(v_bundle_item.id, v_selections);
        v_variant_name := null;
        v_unit_price := v_product.price;
        v_inventory := v_product.inventory_count;
        v_name := coalesce(nullif(trim(v_bundle_item.label), ''), v_product.name);

        if v_sel_variant is not null then
          select * into v_variant from public.product_variants pv
          where pv.id = v_sel_variant and pv.product_id = v_product.id and pv.is_active = true;
          if v_variant.id is null then
            return jsonb_build_object('ok', false, 'error', 'Invalid variant for ' || v_product.name);
          end if;
          v_variant_name := v_variant.name;
          v_unit_price := coalesce(v_variant.price, v_product.price);
          v_inventory := v_variant.inventory_count;
          v_name := v_name || ' — ' || v_variant.name;
        elsif exists (select 1 from public.product_variants pv where pv.product_id = v_product.id and pv.is_active = true) then
          return jsonb_build_object('ok', false, 'error', v_product.name || ' requires a variant selection in this bundle');
        end if;

        v_reserved := public.reserved_inventory_quantity(v_product.id, v_sel_variant);
        if v_inventory - v_reserved < v_bundle_item.quantity * v_qty then
          return jsonb_build_object('ok', false, 'error', v_name || ' has insufficient stock for this bundle');
        end if;

        v_components := v_components || jsonb_build_object(
          'bundle_item_id', v_bundle_item.id,
          'product_id', v_product.id,
          'variant_id', v_sel_variant,
          'variant_name', v_variant_name,
          'name', v_name,
          'slug', v_product.slug,
          'quantity', v_bundle_item.quantity * v_qty,
          'unit_price', v_unit_price
        );
      end loop;

      v_line := v_bundle.price * v_qty;
      v_subtotal := v_subtotal + v_line;
      v_items_out := v_items_out || jsonb_build_object(
        'bundle_id', v_bundle.id,
        'product_id', null,
        'variant_id', null,
        'variant_name', null,
        'name', v_bundle.name,
        'slug', v_bundle.slug,
        'image_url', v_bundle.image_url,
        'unit_price', v_bundle.price,
        'quantity', v_qty,
        'line_total', v_line,
        'is_bundle', true,
        'components', v_components
      );
      continue;
    end if;

    v_variant_id := nullif(v_item->>'variant_id', '')::uuid;
    v_variant_name := null;
    select * into v_product from public.products p
    where p.id = (v_item->>'product_id')::uuid and p.published = true;
    if v_product.id is null then
      return jsonb_build_object('ok', false, 'error', 'Product unavailable');
    end if;

    v_unit_price := v_product.price;
    v_inventory := v_product.inventory_count;
    v_name := v_product.name;
    v_image := v_product.image_url;

    if v_variant_id is not null then
      select * into v_variant from public.product_variants pv
      where pv.id = v_variant_id and pv.product_id = v_product.id and pv.is_active = true;
      if v_variant.id is null then
        return jsonb_build_object('ok', false, 'error', 'Variant unavailable for ' || v_product.name);
      end if;
      v_unit_price := coalesce(v_variant.price, v_product.price);
      v_inventory := v_variant.inventory_count;
      v_variant_name := v_variant.name;
      v_name := v_product.name || ' — ' || v_variant.name;
      v_image := coalesce(v_variant.image_url, v_product.image_url);
    elsif exists (select 1 from public.product_variants pv where pv.product_id = v_product.id and pv.is_active = true) then
      return jsonb_build_object('ok', false, 'error', v_product.name || ' requires a variant selection');
    end if;

    v_reserved := public.reserved_inventory_quantity(v_product.id, v_variant_id);
    if v_inventory - v_reserved < v_qty then
      return jsonb_build_object('ok', false, 'error', v_name || ' has only ' || greatest(0, v_inventory - v_reserved) || ' in stock');
    end if;

    v_line := v_unit_price * v_qty;
    v_subtotal := v_subtotal + v_line;
    v_items_out := v_items_out || jsonb_build_object(
      'product_id', v_product.id,
      'variant_id', v_variant_id,
      'variant_name', v_variant_name,
      'name', v_name,
      'slug', v_product.slug,
      'image_url', v_image,
      'unit_price', v_unit_price,
      'quantity', v_qty,
      'line_total', v_line,
      'is_bundle', false
    );
  end loop;

  v_coupon := public.resolve_coupon_discount(p_coupon_code, v_subtotal);
  if not (v_coupon->>'ok')::boolean then
    return v_coupon;
  end if;
  v_discount := coalesce((v_coupon->>'discount')::numeric, 0);

  v_shipping := public.resolve_shipping_rate(p_shipping_country, v_subtotal - v_discount);
  select coalesce(nullif((select value from public.site_settings where key = 'tax_rate_percent' limit 1), '')::numeric, 0)
  into v_tax_rate;
  v_tax := round(greatest(0, v_subtotal - v_discount) * v_tax_rate / 100, 2);
  v_total := greatest(0, v_subtotal - v_discount) + v_shipping + v_tax;

  return jsonb_build_object(
    'ok', true,
    'currency', v_currency,
    'subtotal', v_subtotal,
    'discount', v_discount,
    'coupon_code', v_coupon->>'code',
    'shipping', v_shipping,
    'tax', v_tax,
    'total', v_total,
    'items', v_items_out
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_get_storefront_product(p_slug text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_row public.products%rowtype;
  v_variants jsonb;
  v_reviews jsonb;
  v_avg numeric;
  v_count int;
  v_delivery text;
begin
  if p_slug is null or btrim(p_slug) = '' then
    return jsonb_build_object('ok', false, 'error', 'Missing slug');
  end if;

  select * into v_row
  from public.products p
  where p.slug = btrim(p_slug) and p.published = true
  limit 1;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'Not found');
  end if;

  select coalesce(jsonb_agg(to_jsonb(v) order by v.sort_order, v.name), '[]'::jsonb)
  into v_variants
  from public.product_variants v
  where v.product_id = v_row.id and v.is_active = true;

  select round(avg(r.rating)::numeric, 1), count(*)::int
  into v_avg, v_count
  from public.product_reviews r
  where r.product_id = v_row.id and r.status = 'approved';

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', r.id,
      'rating', r.rating,
      'title', r.title,
      'body', r.body,
      'created_at', r.created_at,
      'author_label', coalesce(split_part(public.auth_user_email(r.user_id), '@', 1), 'Customer')
    ) order by r.created_at desc
  ), '[]'::jsonb)
  into v_reviews
  from public.product_reviews r
  where r.product_id = v_row.id and r.status = 'approved';

  v_delivery := public.resolve_product_delivery_text(v_row.id);

  return jsonb_build_object(
    'ok', true,
    'product', to_jsonb(v_row),
    'variants', v_variants,
    'reviews', jsonb_build_object(
      'average_rating', coalesce(v_avg, 0),
      'count', coalesce(v_count, 0),
      'items', v_reviews
    ),
    'delivery_text', v_delivery
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_list_cms_media(p_limit integer DEFAULT 48, p_offset integer DEFAULT 0, p_kind text DEFAULT 'image'::text, p_search text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_total bigint;
  v_items jsonb;
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'error', 'Forbidden');
  end if;

  select count(*) into v_total
  from public.cms_media m
  where (p_kind is null or m.kind = p_kind)
    and (
      p_search is null
      or btrim(p_search) = ''
      or coalesce(m.file_name, '') ilike '%' || btrim(p_search) || '%'
    );

  select coalesce(jsonb_agg(to_jsonb(sub)), '[]'::jsonb)
  into v_items
  from (
    select m.*
    from public.cms_media m
    where (p_kind is null or m.kind = p_kind)
      and (
        p_search is null
        or btrim(p_search) = ''
        or coalesce(m.file_name, '') ilike '%' || btrim(p_search) || '%'
      )
    order by m.created_at desc
    limit greatest(coalesce(p_limit, 48), 1)
    offset greatest(coalesce(p_offset, 0), 0)
  ) sub;

  return jsonb_build_object('ok', true, 'items', v_items, 'total', v_total);
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_list_low_stock_products(p_threshold integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_threshold int;
  v_items jsonb;
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'error', 'Forbidden');
  end if;

  select coalesce(
    p_threshold,
    nullif((select value from public.site_settings where key = 'low_stock_threshold' limit 1), '')::int,
    5
  ) into v_threshold;

  select coalesce(jsonb_agg(row_to_json(x.*)), '[]'::jsonb) into v_items
  from (
    select id, name, slug, 'product' as kind, inventory_count as stock, null::text as variant_name
    from public.products
    where published = true and inventory_count <= v_threshold
    union all
    select p.id, p.name || ' — ' || pv.name, p.slug, 'variant' as kind, pv.inventory_count as stock, pv.name as variant_name
    from public.product_variants pv
    join public.products p on p.id = pv.product_id
    where pv.is_active = true and p.published = true and pv.inventory_count <= v_threshold
    order by stock asc, name asc
    limit 100
  ) x;

  return jsonb_build_object('ok', true, 'items', v_items, 'threshold', v_threshold);
end;
$function$

